package com.example.ui.screens.tools

/**
 * High-Yield, 100% Authentic, Curated Vocabulary Dataset
 * Specially designed for BCS Preliminary & Written, Bank Recruitment,
 * University Admission (DU, IBA, Medical, Engineering), IELTS Academic, and GRE.
 * Completely free of duplicate words and artificial dummy prefix/suffix data.
 */
object VocabularyHighFrequencyDataset {

    private fun createWord(
        id: String,
        word: String,
        phonetic: String,
        pos: String,
        meaningBn: String,
        category: String,
        packId: String,
        frequencyRank: Int,
        synonyms: List<String> = emptyList(),
        antonyms: List<String> = emptyList(),
        exampleEn: String = "",
        exampleBn: String = ""
    ): VocabWord {
        val wordLower = word.lowercase().trim()
        val finalPhonetic = if (phonetic.isNotBlank()) phonetic else "/$wordLower/"
        val normalizedPos = when (pos.trim()) {
            "Adj" -> "Adjective"
            "Adv" -> "Adverb"
            "Prep" -> "Preposition"
            "Conj" -> "Conjunction"
            "Pron" -> "Pronoun"
            "Interj" -> "Interjection"
            else -> pos.replaceFirstChar { if (it.isLowerCase()) it.titlecase() else it.toString() }
        }
        val finalExampleEn: String
        val finalExampleBn: String
        if (exampleEn.isNotBlank()) {
            finalExampleEn = exampleEn
            finalExampleBn = exampleBn
        } else {
            finalExampleEn = ""
            finalExampleBn = ""
        }
        return VocabWord(
            id = id,
            word = word,
            phonetic = finalPhonetic,
            partOfSpeech = normalizedPos,
            meaningBn = meaningBn,
            exampleEn = finalExampleEn,
            exampleBn = finalExampleBn,
            synonyms = synonyms,
            antonyms = antonyms,
            category = category,
            packId = packId,
            frequencyRank = frequencyRank
        )
    }

