    fun getIelts4000Pack(): List<VocabWord> {
        val list = mutableListOf<VocabWord>()
        list.addAll(VocabularyDataPacks.ieltsWords)

        val ieltsData = listOf(
            Triple("Manipulate", "Verb", "চতুরতার সাথে নিয়ন্ত্রণ করা"),
            Triple("Marginal", "Adj", "প্রান্তিক, যৎসামান্য"),
