        )

        ieltsData.forEachIndexed { index, (word, pos, meaning) ->
            list.add(
                createWord(
                    id = "ie_hf_${index + 1}",
                    word = word,
                    phonetic = "/${word.lowercase()}/",
                    pos = pos,
                    meaningBn = meaning,
                    category = "IELTS",
                    packId = "ielts_4000",
                    frequencyRank = index + 1
                )
            )
        }

        return list
    }

