        )

        bcsData.forEachIndexed { index, (word, pos, meaning) ->
            list.add(
                createWord(
                    id = "bc_hf_${index + 1}",
                    word = word,
                    phonetic = "/${word.lowercase()}/",
                    pos = pos,
                    meaningBn = meaning,
                    category = "BCS",
                    packId = "bcs_5000",
                    frequencyRank = index + 1
                )
            )
        }

        return list
    }

